import re
from decimal import Decimal, localcontext, InvalidOperation

# High working precision so that quantize/comparison operations are exact
# regardless of the caller's global decimal context precision.
_WORK_PREC = 100

_MAX = Decimal("1000000.00")
_CENT = Decimal("0.01")
_ZERO = Decimal(0)

# Full-match ASCII grammar: optional sign, digits before the point, and
# (if a point is present) digits after it.  No whitespace, exponents,
# underscores, or non-ASCII digits.
_STRING_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)


def _validated(value):
    """Validate a finite, in-range, cents-exact Decimal and return it quantized to cents."""
    if not value.is_finite():
        raise ValueError("amount must be a finite number")
    if value < _ZERO:
        raise ValueError("amount must not be negative")
    if value == _ZERO:
        raise ValueError("amount must not be zero")
    with localcontext() as ctx:
        ctx.prec = _WORK_PREC
        if value > _MAX:
            raise ValueError("amount exceeds 1000000.00")
        try:
            cents = value.quantize(_CENT)
        except InvalidOperation:
            raise ValueError("amount is not exactly representable in cents")
        if cents != value:
            raise ValueError("amount is not exactly representable in cents")
        return cents


def parse_amount(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, int):
        return _validated(Decimal(value))
    if isinstance(value, Decimal):
        return _validated(value)
    if isinstance(value, str):
        if _STRING_PATTERN.fullmatch(value) is None:
            raise ValueError("string does not match the amount grammar")
        return _validated(Decimal(value))
    raise ValueError(
        "amount must be a Decimal, an int, or a string matching the amount grammar"
    )


def format_amount(value):
    return format(value, ".2f")
